  S.seedUsed = P.seed;
  const fr = i => { const s = Math.sin(i*127.1 + P.seed*311.7) * 43758.5453; return s - Math.floor(s); };
  S.forms = [];
  for (let k = 0; k < 8; k++) {
    S.forms.push({ c0: 0.06 + fr(k*3+1)*0.9, rate: 0.04 + fr(k*3+2)*0.22, phase: fr(k*3+3)*6.28, w: 0.01 + fr(k*7+4)*0.035, h: 0.4 + fr(k*7+5)*0.6 });
  }
