// colormap stops (rgb 0..1), 5 anchors
const MAPS = {
  magma:  [[0,0,.02],[.28,.06,.42],[.68,.19,.42],[.98,.55,.38],[.99,.96,.86]],
  inferno:[[0,0,.02],[.30,.06,.35],[.72,.21,.30],[.97,.55,.04],[.98,1,.64]],
