// per-frame drivers
const t = K.t, spd = 0.5 + P.speed * 1.0, dr = 0.35 + P.drift * 1.1;
const sec = K.section | 0, inten = K.intensity;
const zoom = 0.4 + P.scale * 1.2, pan = (P.x - 0.5) * 0.6;
